package br.tcc.checkout.model;

import java.math.BigDecimal;

public enum ModalidadeEntrega {
    ECONOMICA("ECONOMICA", new BigDecimal("12.00"), new BigDecimal("2.00"), 7) {
        @Override
        public BigDecimal calcularFrete(BigDecimal pesoKg) {
            return base.add(taxaPorKg.multiply(pesoKg));
        }
    },
    EXPRESSA("EXPRESSA", new BigDecimal("25.00"), new BigDecimal("4.50"), 2) {
        @Override
        public BigDecimal calcularFrete(BigDecimal pesoKg) {
            return base.add(taxaPorKg.multiply(pesoKg));
        }
    },
    RETIRADA_LOJA("RETIRADA_LOJA", BigDecimal.ZERO, BigDecimal.ZERO, 1) {
        @Override
        public BigDecimal calcularFrete(BigDecimal pesoKg) {
            return BigDecimal.ZERO;
        }
    },
    MOTOBOY("MOTOBOY", new BigDecimal("18.00"), BigDecimal.ZERO, 0) {
        @Override
        public BigDecimal calcularFrete(BigDecimal pesoKg) {
            return base;
        }
    };

    private final String codigo;
    protected final BigDecimal base;
    protected final BigDecimal taxaPorKg;
    private final Integer prazo;

    ModalidadeEntrega(String codigo, BigDecimal base, BigDecimal taxaPorKg, Integer prazo) {
        this.codigo = codigo;
        this.base = base;
        this.taxaPorKg = taxaPorKg;
        this.prazo = prazo;
    }

    public static ModalidadeEntrega buscar(String codigo) {
        if (codigo == null) return null;
        for (ModalidadeEntrega m : ModalidadeEntrega.values()) {
            if (m.codigo.equals(codigo)) {
                return m;
            }
        }
        return null;
    }

    public abstract BigDecimal calcularFrete(BigDecimal pesoKg);

    public Integer getPrazo() {
        return prazo;
    }

    public boolean validarPeso(BigDecimal pesoKg) {
        if (this == MOTOBOY) {
            return pesoKg.compareTo(new BigDecimal("5")) <= 0;
        }
        return true;
    }
}

