package br.tcc.checkout.service;

import br.tcc.checkout.dto.CheckoutRequest;
import br.tcc.checkout.dto.CheckoutResponse;
import br.tcc.checkout.dto.ItemRequest;
import br.tcc.checkout.exception.CheckoutException;
import br.tcc.checkout.model.Cupom;
import br.tcc.checkout.model.FormaPagamento;
import br.tcc.checkout.model.ModalidadeEntrega;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

@Service
public class CheckoutService {

    private static final BigDecimal PIX_DISCOUNT = new BigDecimal("0.05");
    private static final BigDecimal BOLETO_TAX = new BigDecimal("3.49");
    private static final BigDecimal CARTAO_MONTHLY_RATE = new BigDecimal("0.0199");
    private static final BigDecimal BOLETO_LIMIT = new BigDecimal("1000.00");
    private static final int SCALE = 2;

    public CheckoutResponse calcular(CheckoutRequest request) {
        validarPedido(request);

        List<ItemRequest> itens = request.getItens();
        ModalidadeEntrega modalidade = ModalidadeEntrega.buscar(request.getModalidadeEntrega());
        Cupom cupom = request.getCupom() != null ? Cupom.buscar(request.getCupom()) : null;
        FormaPagamento forma = FormaPagamento.buscar(request.getFormaPagamento());
        Integer parcelas = request.getParcelas() != null ? request.getParcelas() : 1;

        validarModalidade(modalidade);
        validarForma(forma, parcelas);

        // Validar que o cupom existe
        if (request.getCupom() != null && cupom == null) {
            throw new CheckoutException("CUPOM_INVALIDO");
        }

        BigDecimal pesoTotal = calcularPeso(itens);
        validarPesoParaModalidade(modalidade, pesoTotal);

        // Calcular subtotal, aplicando desconto LEVE3PAGUE2 se necessário
        BigDecimal subtotal = calcularSubtotal(cupom, itens);

        BigDecimal frete = calcularFrete(modalidade, pesoTotal);

        // Calcular desconto do cupom
        BigDecimal desconto = calcularDesconto(cupom, subtotal, frete);

        // Validar condições do cupom
        if (cupom == Cupom.MENOS50 && subtotal.compareTo(new BigDecimal("300.00")) < 0) {
            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
        }

        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete);

        validarBoleto(forma, totalPedido);

        BigDecimal ajustePagamento = calcularAjustePagamento(forma, totalPedido, parcelas);

        BigDecimal totalFinal = totalPedido.add(ajustePagamento);
        totalFinal = arredondar(totalFinal);

        BigDecimal valorParcela = calcularValorParcela(forma, totalFinal, parcelas);

        return new CheckoutResponse(
            arredondar(subtotal),
            arredondar(desconto),
            arredondar(frete),
            modalidade.getPrazo(),
            arredondar(ajustePagamento),
            totalFinal,
            parcelas,
            arredondar(valorParcela)
        );
    }

    private void validarPedido(CheckoutRequest request) {
        if (request.getItens() == null || request.getItens().isEmpty()) {
            throw new CheckoutException("PEDIDO_INVALIDO");
        }

        for (ItemRequest item : request.getItens()) {
            if (item.getPrecoUnitario() == null || item.getPrecoUnitario() <= 0 ||
                item.getQuantidade() == null || item.getQuantidade() <= 0 ||
                item.getPesoKg() == null || item.getPesoKg() < 0) {
                throw new CheckoutException("PEDIDO_INVALIDO");
            }
        }
    }

    private void validarModalidade(ModalidadeEntrega modalidade) {
        if (modalidade == null) {
            throw new CheckoutException("MODALIDADE_INVALIDA");
        }
    }

    private void validarForma(FormaPagamento forma, Integer parcelas) {
        if (forma == null) {
            throw new CheckoutException("FORMA_PAGAMENTO_INVALIDA");
        }

        if (parcelas < 1 || parcelas > 12) {
            throw new CheckoutException("PARCELAMENTO_INVALIDO");
        }

        if ((forma == FormaPagamento.PIX || forma == FormaPagamento.BOLETO) && parcelas != 1) {
            throw new CheckoutException("PARCELAMENTO_INVALIDO");
        }

        if (forma == FormaPagamento.CARTAO && parcelas > 12) {
            throw new CheckoutException("PARCELAMENTO_INVALIDO");
        }
    }

    private BigDecimal calcularPeso(List<ItemRequest> itens) {
        BigDecimal pesoTotal = BigDecimal.ZERO;
        for (ItemRequest item : itens) {
            BigDecimal peso = new BigDecimal(item.getPesoKg());
            pesoTotal = pesoTotal.add(peso.multiply(new BigDecimal(item.getQuantidade())));
        }
        return pesoTotal;
    }

    private void validarPesoParaModalidade(ModalidadeEntrega modalidade, BigDecimal peso) {
        if (!modalidade.validarPeso(peso)) {
            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
        }
    }

    private BigDecimal calcularSubtotal(Cupom cupom, List<ItemRequest> itens) {
        BigDecimal subtotal = BigDecimal.ZERO;

        if (cupom == Cupom.LEVE3PAGUE2) {
            // LEVE3PAGUE2: a cada 3 unidades de um mesmo item, uma sai de graça
            for (ItemRequest item : itens) {
                BigDecimal preco = new BigDecimal(item.getPrecoUnitario());
                Integer quantidade = item.getQuantidade();

                // Calcular quantas unidades pagam (a cada 3, 2 pagam)
                Integer unidadesGratis = quantidade / 3;
                Integer unidadesPagas = quantidade - unidadesGratis;

                BigDecimal itemTotal = preco.multiply(new BigDecimal(unidadesPagas));
                itemTotal = arredondar(itemTotal);
                subtotal = subtotal.add(itemTotal);
            }
            return arredondar(subtotal);
        } else {
            // Sem cupom ou com cupom que não afeta preço
            for (ItemRequest item : itens) {
                BigDecimal preco = new BigDecimal(item.getPrecoUnitario());
                BigDecimal quantidade = new BigDecimal(item.getQuantidade());
                BigDecimal itemTotal = preco.multiply(quantidade);
                itemTotal = arredondar(itemTotal);
                subtotal = subtotal.add(itemTotal);
            }
            return arredondar(subtotal);
        }
    }

    private BigDecimal calcularDesconto(Cupom cupom, BigDecimal subtotal, BigDecimal frete) {
        if (cupom == null) {
            return BigDecimal.ZERO;
        }

        switch (cupom) {
            case BEMVINDO10:
                return arredondar(subtotal.multiply(new BigDecimal("0.10")));

            case MENOS50:
                return arredondar(new BigDecimal("50.00"));

            case FRETEGRATIS:
                return arredondar(frete);

            case LEVE3PAGUE2:
                return BigDecimal.ZERO;

            default:
                return BigDecimal.ZERO;
        }
    }

    private BigDecimal calcularFrete(ModalidadeEntrega modalidade, BigDecimal pesoTotal) {
        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
        return arredondar(frete);
    }

    private void validarBoleto(FormaPagamento forma, BigDecimal totalPedido) {
        if (forma == FormaPagamento.BOLETO && totalPedido.compareTo(BOLETO_LIMIT) > 0) {
            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
        }
    }

