    if (forma == FormaPagamento.CARTAO && parcelas > 3) {
        BigDecimal taxa = CARTAO_MONTHLY_RATE;
        BigDecimal numerador = totalFinal.multiply(taxa);
        // (1 + taxa)^n
        BigDecimal base = BigDecimal.ONE.add(taxa).pow(parcelas);
