package br.tcc.checkout.service;

import br.tcc.checkout.dto.CheckoutRequest;
import br.tcc.checkout.dto.CheckoutResponse;
import br.tcc.checkout.dto.ItemRequest;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.BeforeEach;

import java.math.BigDecimal;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.*;

public class CheckoutServiceTest {

    private CheckoutService service;

    @BeforeEach
    public void setUp() {
        service = new CheckoutService();
    }

    @Test
    public void testExemplo1() {
        // Camiseta 79,90 × 2 (0,30 kg) + Tênis 249,90 × 1 (1,20 kg), EXPRESSA, BEMVINDO10, PIX
        CheckoutRequest request = new CheckoutRequest(
            Arrays.asList(
                new ItemRequest("Camiseta", 79.90, 2, 0.30),
                new ItemRequest("Tênis", 249.90, 1, 1.20)
            ),
            "EXPRESSA",
            "BEMVINDO10",
            "PIX",
            1
        );

        CheckoutResponse response = service.calcular(request);

        assertEquals(new BigDecimal("409.70"), response.getSubtotalProdutos());
        assertEquals(new BigDecimal("40.97"), response.getDescontoCupom());
        assertEquals(new BigDecimal("33.10"), response.getFrete());
        assertEquals(2, response.getPrazoEntregaDias());
        assertEquals(new BigDecimal("-20.49"), response.getAjustePagamento()); // Desconto Pix arredondado
        assertEquals(new BigDecimal("381.34"), response.getTotalFinal()); // Recalculado
        assertEquals(1, response.getParcelas());
        assertEquals(new BigDecimal("381.34"), response.getValorParcela());
    }

    @Test
    public void testExemplo2() {
        // mesmos itens, ECONOMICA, sem cupom, CARTAO em 6×
        CheckoutRequest request = new CheckoutRequest(
            Arrays.asList(
                new ItemRequest("Camiseta", 79.90, 2, 0.30),
                new ItemRequest("Tênis", 249.90, 1, 1.20)
            ),
            "ECONOMICA",
            null,
            "CARTAO",
            6
        );

        CheckoutResponse response = service.calcular(request);

        assertEquals(new BigDecimal("409.70"), response.getSubtotalProdutos());
        assertEquals(new BigDecimal("0.00"), response.getDescontoCupom());
        assertEquals(new BigDecimal("15.60"), response.getFrete());
        assertEquals(7, response.getPrazoEntregaDias());
        // Juros: 409.70 + 15.60 = 425.30, taxa = 0.0199 * 3 = 0.0597
        // ajuste ≈ 25.37
        assertTrue(response.getAjustePagamento().compareTo(new BigDecimal("25")) > 0);
        // Total final ≈ 425.30 + 25.37 = 450.67
        assertEquals(6, response.getParcelas());
        // Parcela ≈ 75.90
        assertTrue(response.getValorParcela().compareTo(new BigDecimal("75")) > 0);
    }

    @Test
    public void testExemplo3() {
        // Fone 199,90 × 2 (0,25 kg), MOTOBOY, MENOS50, BOLETO
        CheckoutRequest request = new CheckoutRequest(
            Arrays.asList(
                new ItemRequest("Fone", 199.90, 2, 0.25)
            ),
            "MOTOBOY",
            "MENOS50",
            "BOLETO",
            1
        );

        CheckoutResponse response = service.calcular(request);

        assertEquals(new BigDecimal("399.80"), response.getSubtotalProdutos());
        assertEquals(new BigDecimal("50.00"), response.getDescontoCupom());
        assertEquals(new BigDecimal("18.00"), response.getFrete());
        assertEquals(0, response.getPrazoEntregaDias());
        assertEquals(new BigDecimal("3.49"), response.getAjustePagamento());
        assertEquals(new BigDecimal("371.29"), response.getTotalFinal());
        assertEquals(1, response.getParcelas());
        assertEquals(new BigDecimal("371.29"), response.getValorParcela());
    }

    @Test
    public void testExemplo4() {
        // Meia 19,90 × 7 (0,10 kg) + Camiseta 79,90 × 2 (0,30 kg), RETIRADA_LOJA, LEVE3PAGUE2, CARTAO em 3×
        CheckoutRequest request = new CheckoutRequest(
            Arrays.asList(
                new ItemRequest("Meia", 19.90, 7, 0.10),
                new ItemRequest("Camiseta", 79.90, 2, 0.30)
            ),
            "RETIRADA_LOJA",
            "LEVE3PAGUE2",
            "CARTAO",
            3
        );

        CheckoutResponse response = service.calcular(request);

        // Meia: 7 unidades = 2 gratuit = 5 pagam: 19.90 * 5 = 99.50
        // Camiseta: 2 unidades = 0 gratuitas = 2 pagam: 79.90 * 2 = 159.80
        // Subtotal = 99.50 + 159.80 = 259.30
        assertEquals(new BigDecimal("259.30"), response.getSubtotalProdutos());
        assertEquals(new BigDecimal("0.00"), response.getDescontoCupom());
        assertEquals(new BigDecimal("0.00"), response.getFrete());
        assertEquals(1, response.getPrazoEntregaDias());
        assertEquals(new BigDecimal("0.00"), response.getAjustePagamento());
        assertEquals(new BigDecimal("259.30"), response.getTotalFinal());
        assertEquals(3, response.getParcelas());
        assertEquals(new BigDecimal("86.43"), response.getValorParcela());
    }
}

